import System.Exception;import System.ArgumentException;import System.ArgumentOutOfRangeException;import System.Globalization.NumberFormatInfo;import System.Type;import System.IUtf8SpanFormattable;import System.ISpanFormattable;import System.Span;import System.ReadOnlySpan;import System.Decimal;import System.IComparable;import System.IFormattable;import System.IFormatProvider;import System.InvalidOperationException;import java.nio.file.*;import java.util.*;
class DecimalCustomTokenTerminationProbe {
 interface Action{void run();}
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String text(String s){if(s.equals("~"))return null;StringBuilder b=new StringBuilder();if(!s.isEmpty())for(String u:s.split(","))b.append((char)Integer.parseInt(u));return b.toString();}
 static int[] sizes(String s){if(s.equals("~"))return null;if(s.isEmpty())return new int[0];String[] p=s.split(",");int[] a=new int[p.length];for(int i=0;i<a.length;i++)a[i]=Integer.parseInt(p[i]);return a;}
 static String csv(int[] a){StringJoiner j=new StringJoiner(",");for(int v:a)j.add(Integer.toString(v));return j.toString();}
 static String outcome(Action a){try{a.run();return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),e instanceof ArgumentOutOfRangeException x&&x.get_ActualValue()!=null?x.get_ActualValue().toString():"~");}}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 static String flag(boolean b){return b?"1":"0";}
 static NumberFormatInfo custom(){NumberFormatInfo n=new NumberFormatInfo();n.set_NegativeSign("~");n.set_PositiveSign("^");n.set_NumberDecimalSeparator("@");n.set_NumberGroupSeparator("_");n.set_NumberGroupSizes(new int[]{2,3});n.set_CurrencySymbol("USD");n.set_CurrencyDecimalSeparator(":");n.set_CurrencyGroupSeparator("'");n.set_CurrencyGroupSizes(new int[]{3,2});n.set_CurrencyPositivePattern(2);n.set_CurrencyNegativePattern(14);n.set_NumberNegativePattern(4);n.set_PercentSymbol("%!");return n;}
 static String compare(IComparable value,Object other){try{return "OK|"+value.CompareTo(other);}catch(Exception e){return error(e);}}
 static String format(IFormattable value,String f,IFormatProvider provider){try{return "OK|"+units(value.ToString(f,provider));}catch(Exception e){return error(e);}}
 static String error(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),"~");}
 static NumberFormatInfo symbols(String profile){NumberFormatInfo n=custom();if(profile.equals("supplementary")){n.set_NegativeSign(new String(new char[]{(char)0xd83d,(char)0xde80}));n.set_PositiveSign(String.valueOf((char)0xff0b));n.set_NumberDecimalSeparator(String.valueOf((char)0x066b));n.set_NumberGroupSeparator(String.valueOf((char)0x202f));n.set_CurrencySymbol(new String(new char[]{(char)0x20ac,(char)0xd83d,(char)0xdcb7}));n.set_CurrencyGroupSeparator(String.valueOf((char)0x2009));n.set_PercentSymbol(String.valueOf((char)0x066a));}else{n.set_NegativeSign(String.valueOf((char)0xd800));n.set_PositiveSign(String.valueOf((char)0xdc00));n.set_CurrencySymbol(new String(new char[]{'u',(char)0xd800,'v',(char)0xdc00}));n.set_PercentSymbol(String.valueOf((char)0xdc00));}return n;}
 static String bytes(byte[] a){StringJoiner j=new StringJoiner(",");for(byte v:a)j.add(Integer.toString(v&255));return j.toString();}
 static final class Actor implements IFormatProvider{final String profile;final char[] chars;final byte[] bytes;final int[] written;final InvalidOperationException failure;final Object result;int calls;Type lastType;Actor(String profile,char[] chars,byte[] bytes,int[] written){this.profile=profile;this.chars=chars;this.bytes=bytes;this.written=written;this.failure=profile.equals("throwing")?new InvalidOperationException("provider failure"):null;this.result=profile.equals("wrong")?"wrong":profile.equals("custom")?custom():null;}public Object GetFormat(Type type){calls++;lastType=type;written[0]=77;if(chars!=null&&chars.length>0){chars[0]='!';chars[chars.length-1]='?';}if(bytes!=null&&bytes.length>0){bytes[0]=17;bytes[bytes.length-1]=34;}if(failure!=null)throw failure;return result;}}
 public static void main(String[] args)throws java.lang.Exception{List<String> lines=Files.readAllLines(Path.of(args[0]));Map<Integer,int[]> bits=new HashMap<>();for(String line:lines){String[] p=line.split("\t",-1);if(p[0].equals("B"))bits.put(Integer.parseInt(p[1]),sizes(p[2]));}int calls=0,groups=0;for(String line:lines){String[] p=line.split("\t",-1);if(p[0].equals("B"))continue;Decimal value=new Decimal(bits.get(Integer.parseInt(p[1])));String format=text(p[2]);if(p[0].equals("R")){Actor actor=new Actor(p[3],null,null,new int[]{99});String actual;try{actual="OK|"+units(((IFormattable)value).ToString(format,actor));}catch(Exception e){actual=error(e);}check(actual,p[4],line);check(Integer.toString(actor.calls)+"|"+flag(actor.lastType==Type.GetType("System.Globalization.NumberFormatInfo")),p[5]+"|"+p[6],"reference callback");check(csv(Decimal.GetBits(value)),p[7],"reference bits");calls++;groups+=3;continue;}boolean isByte=p[4].startsWith("byte"),slice=p[4].endsWith("span");int capacity=Integer.parseInt(p[5]),offset=Integer.parseInt(p[6]),suffix=Integer.parseInt(p[7]);char[] chars=isByte?null:new char[capacity+offset+suffix];byte[] bytes=isByte?new byte[capacity+offset+suffix]:null;if(isByte)Arrays.fill(bytes,(byte)0xa5);else Arrays.fill(chars,'#');int[] written={99};Actor actor=new Actor(p[3],chars,bytes,written);String actual;boolean sameError=false;try{boolean ok;if(isByte)ok=slice?value.TryFormat(Span.OfUtf8Bytes(bytes).Slice(offset,capacity),written,ReadOnlySpan.OfChars((format==null?"":format).toCharArray()),actor):((IUtf8SpanFormattable)value).TryFormat(bytes,written,format,actor);else ok=slice?value.TryFormat(Span.OfChars(chars).Slice(offset,capacity),written,ReadOnlySpan.OfChars((format==null?"":format).toCharArray()),actor):((ISpanFormattable)value).TryFormat(chars,written,format,actor);actual="OK|"+flag(ok);}catch(Exception e){actual=error(e);sameError=actor.failure!=null&&actor.failure==e;}check(actual,p[8],line);check(Integer.toString(written[0])+"|"+(isByte?bytes(bytes):units(new String(chars))),p[9]+"|"+p[10],"callback buffer "+line);check(Integer.toString(actor.calls)+"|"+flag(actor.lastType==Type.GetType("System.Globalization.NumberFormatInfo"))+"|"+flag(sameError),p[11]+"|"+p[12]+"|"+p[13],"callback identity "+line);check(csv(Decimal.GetBits(value)),p[14],"immutable Decimal "+line);calls++;groups+=4;}java.lang.System.out.println("PASS Decimal specifier/literal boundaries calls="+calls+" groups="+groups);}
}
